class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        adj = [[] for _ in range(n)]
        for a, b, toll in highways:
            adj[a].append((b, toll))
            adj[b].append((a, toll))

        best = -1

        def dfs(city, visited, cost, left):
            nonlocal best
            if left == 0:
                best = max(best, cost)
                return
            for nxt, toll in adj[city]:
                if not visited >> nxt & 1:
                    dfs(nxt, visited | 1 << nxt, cost + toll, left - 1)

        for s in range(n):
            dfs(s, 1 << s, 0, k)
        return best

