class Solution {
public:
    int best = -1;

    void dfs(int city, int visited, long long cost, int left,
             vector<vector<pair<int,int>>>& adj) {
        if (left == 0) {
            best = max(best, (int)cost);
            return;
        }
        for (auto& [nxt, toll] : adj[city]) {
            if (!(visited >> nxt & 1)) {
                dfs(nxt, visited | 1 << nxt, cost + toll, left - 1, adj);
            }
        }
    }

    int maximumCost(int n, vector<vector<int>>& highways, int k) {
        vector<vector<pair<int,int>>> adj(n);
        for (auto& h : highways) {
            adj[h[0]].push_back({h[1], h[2]});
            adj[h[1]].push_back({h[0], h[2]});
        }
        for (int s = 0; s < n; s++) {
            dfs(s, 1 << s, 0, k, adj);
        }
        return best;
    }
};

