class Solution {
    private int best = -1;

    private void dfs(int city, int visited, int cost, int left, List<int[]>[] adj) {
        if (left == 0) {
            best = Math.max(best, cost);
            return;
        }
        for (int[] e : adj[city]) {
            if ((visited >> e[0] & 1) == 0) {
                dfs(e[0], visited | (1 << e[0]), cost + e[1], left - 1, adj);
            }
        }
    }

    public int maximumCost(int n, int[][] highways, int k) {
        List<int[]>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] h : highways) {
            adj[h[0]].add(new int[]{h[1], h[2]});
            adj[h[1]].add(new int[]{h[0], h[2]});
        }
        for (int s = 0; s < n; s++) {
            dfs(s, 1 << s, 0, k, adj);
        }
        return best;
    }
}

