class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        if k >= n:
            return -1
        NEG = float("-inf")
        w = [[NEG] * n for _ in range(n)]
        for a, b, toll in highways:
            w[a][b] = w[b][a] = toll
        dp = [[NEG] * n for _ in range(1 << n)]
        for i in range(n):
            dp[1 << i][i] = 0
        ans = -1
        for mask in range(1 << n):
            for i in range(n):
                cur = dp[mask][i]
                if cur == NEG:
                    continue
                if bin(mask).count("1") == k + 1:
                    ans = max(ans, cur)
                for j in range(n):
                    if not mask >> j & 1 and w[i][j] != NEG:
                        nm = mask | 1 << j
                        dp[nm][j] = max(dp[nm][j], cur + w[i][j])
        return ans

