class Solution {
    public int maximumCost(int n, int[][] highways, int k) {
        if (k >= n) return -1;
        final int NEG = Integer.MIN_VALUE / 2;
        int[][] w = new int[n][n];
        for (int[] row : w) Arrays.fill(row, NEG);
        for (int[] h : highways) {
            w[h[0]][h[1]] = w[h[1]][h[0]] = h[2];
        }
        int[][] dp = new int[1 << n][n];
        for (int[] row : dp) Arrays.fill(row, NEG);
        for (int i = 0; i < n; i++) dp[1 << i][i] = 0;
        int ans = -1;
        for (int mask = 1; mask < (1 << n); mask++) {
            for (int i = 0; i < n; i++) {
                if (dp[mask][i] == NEG) continue;
                if (Integer.bitCount(mask) == k + 1) ans = Math.max(ans, dp[mask][i]);
                for (int j = 0; j < n; j++) {
                    if ((mask >> j & 1) == 0 && w[i][j] != NEG) {
                        int nm = mask | (1 << j);
                        dp[nm][j] = Math.max(dp[nm][j], dp[mask][i] + w[i][j]);
                    }
                }
            }
        }
        return ans;
    }
}

