var maximumCost = function(n, highways, k) {
    if (k >= n) return -1;
    const NEG = -Infinity;
    const w = Array.from({length: n}, () => new Array(n).fill(NEG));
    for (const [a, b, toll] of highways) {
        w[a][b] = toll;
        w[b][a] = toll;
    }
    const dp = Array.from({length: 1 << n}, () => new Array(n).fill(NEG));
    for (let i = 0; i < n; i++) dp[1 << i][i] = 0;
    let ans = -1;
    for (let mask = 1; mask < (1 << n); mask++) {
        for (let i = 0; i < n; i++) {
            if (dp[mask][i] === NEG) continue;
            let bits = 0;
            for (let m = mask; m; m >>= 1) bits += m & 1;
            if (bits === k + 1) ans = Math.max(ans, dp[mask][i]);
            for (let j = 0; j < n; j++) {
                if (!(mask >> j & 1) && w[i][j] !== NEG) {
                    const nm = mask | (1 << j);
                    dp[nm][j] = Math.max(dp[nm][j], dp[mask][i] + w[i][j]);
                }
            }
        }
    }
    return ans;
};
